item.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ
	"ОжидаемыеРасчеты" КАК Таблица,
	"" КАК Раздел,
	ЗаказыПокупателей.ЗаказНаПроизводство КАК Регистратор,
	ЗаказыПокупателей.Контрагент КАК Контрагент,
	ЗаказыПокупателей.Организация КАК Организация,
	ВЫРАЗИТЬ(ЗаказыПокупателей.ЗаказНаПроизводство КАК Документ.ЗаказПокупателя).Дата КАК ПериодСекунда,
	ЗаказыПокупателей.ЗаказНаПроизводство.ТекущийСтатус КАК ТекущийСтатус,
	Заказ.Номенклатура КАК ОР_Номенклатура,
	ЗаказыПокупателей.КоличествоОстаток КАК ОР_Количество,
	Заказ.Номенклатура.БазоваяЕдиницаИзмерения КАК ОР_ЕдиницаИзмерения,

	//++ #12873
	//ВЫБОР
	//	КОГДА ЕСТЬNULL(Заказ.Количество, 0) = 0
	//		ТОГДА ЕСТЬNULL(Заказ.Сумма, 0)
	//	ИНАЧЕ ЕСТЬNULL(Заказ.Сумма, 0) / ЕСТЬNULL(Заказ.Количество, 0)
	//КОНЕЦ КАК ОР_Цена,
	ВЫБОР
		КОГДА ЗаказыПокупателей.КоличествоОстаток = 0
			ТОГДА ЗаказыПокупателей.СуммаОстаток
		ИНАЧЕ ЗаказыПокупателей.СуммаОстаток / ЗаказыПокупателей.КоличествоОстаток
	КОНЕЦ КАК ОР_Цена, 
	//ВЫБОР
	//	КОГДА ЕСТЬNULL(Заказ.Количество, 0) = 0
	//		ТОГДА ЕСТЬNULL(Заказ.Сумма, 0)
	//	ИНАЧЕ ЗаказыПокупателей.КоличествоОстаток / ЕСТЬNULL(Заказ.Количество, 0) * ЕСТЬNULL(Заказ.Сумма, 0)
	//КОНЕЦ КАК ОР_Сумма,
	//ВЫБОР
	//	КОГДА ЕСТЬNULL(Заказ.Количество, 0) = 0
	//		ТОГДА ЕСТЬNULL(Заказ.Сумма, 0)
	//	ИНАЧЕ ЗаказыПокупателей.КоличествоОстаток / ЕСТЬNULL(Заказ.Количество, 0) * ЕСТЬNULL(Заказ.Сумма, 0)
	//КОНЕЦ КАК ОР_СуммаПриходЗаказ,
	ЗаказыПокупателей.СуммаОстаток КАК ОР_Сумма,
	ЗаказыПокупателей.СуммаОстаток КАК ОР_СуммаОборот,
	ЗаказыПокупателей.СуммаОстаток КАК ОР_СуммаПриходЗаказ,
	//-- #12873 

	0 КАК ОР_Расход,
	//, 0 как СуммаНачальныйОстаток
	//, 0 КАК СуммаКонечныйОстаток

	ЕСТЬNULL(БонусыКонтрагентовОбороты.СуммаОборот, 0) КАК СуммаБонусовОборот, // №13246
	ЕСТЬNULL(БонусыКонтрагентовОбороты.СуммаПриход, 0) КАК СуммаБонусовПриход,
	ЕСТЬNULL(БонусыКонтрагентовОбороты.СуммаРасход, 0) КАК СуммаБонусовРасход
ИЗ
	РегистрНакопления.ЗаказыПокупателей.Остатки({(&КонецПериода)},
		//#16100 исключаем заказы в статусе "Новый" 
		НЕ ВЫРАЗИТЬ(ЗаказНаПроизводство КАК Документ.ЗаказПокупателя).ТекущийСтатус = ЗНАЧЕНИЕ(Справочник.СтатусыЗаказовПокупателей.Новый)	
		) КАК ЗаказыПокупателей

		ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ
			ЗаказТовары.Ссылка КАК Ссылка,
			ЗаказТовары.Номенклатура КАК Номенклатура,
			ЗаказТовары.ХарактеристикаНоменклатуры КАК ХарактеристикаНоменклатуры,
			ЗаказТовары.СерияНоменклатуры КАК СерияНоменклатуры,
			СУММА(ЗаказТовары.Количество) КАК Количество,
			СУММА(ЗаказТовары.Сумма) КАК Сумма
		ИЗ
			Документ.ЗаказПокупателя.Товары КАК ЗаказТовары

		СГРУППИРОВАТЬ ПО
			ЗаказТовары.Ссылка,
			ЗаказТовары.Номенклатура,
			ЗаказТовары.ХарактеристикаНоменклатуры,
			ЗаказТовары.СерияНоменклатуры) КАК Заказ
		ПО ЗаказыПокупателей.ЗаказНаПроизводство = Заказ.Ссылка
			И (Заказ.Номенклатура = ЗаказыПокупателей.Номенклатура)
			И (Заказ.ХарактеристикаНоменклатуры = ЗаказыПокупателей.ХарактеристикаНоменклатуры)
			И (Заказ.СерияНоменклатуры = ЗаказыПокупателей.СерияНоменклатуры)

		// №13246
		ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.БонусыКонтрагентов.Обороты(,, Авто) КАК БонусыКонтрагентовОбороты
		ПО ЗаказыПокупателей.ЗаказНаПроизводство = БонусыКонтрагентовОбороты.Регистратор

ГДЕ
	ТИПЗНАЧЕНИЯ(ЗаказыПокупателей.ЗаказНаПроизводство) = ТИП(Документ.ЗаказПокупателя)
	// #13516 закомментировано: если были возвраты по выполненным заказам с признаком повторной отгрузки,
	// то они не попадают в отчет
	//И ЗаказыПокупателей.ЗаказНаПроизводство.ТекущийСтатус = ЗНАЧЕНИЕ(Справочник.СтатусыЗаказовПокупателей.ВРаботе)

// №13246 // запрос строится именно в таком варианте: // ВзаиморасчетыСКонтрагентамиОстаткиИОбороты - берутся для получения контрагентов, по которым будет выводится строчка "Начальный долг" // если брать только остатки на начало периода, или только обороты, то каких-то контрагентов может не оказаться и строчки "Начальный долг не будет" // с этого запроса не используется получение СуммаНачальныйОстаток, т.к. она виртуальная и рассчитывается на каждый регистратор
ВЫБРАТЬ РАЗРЕШЕННЫЕ 1 КАК Приоритет, "Остатки" КАК Таблица, "ВзаиморасчетыСКонтрагентами" КАК Раздел, "Начальный остаток" КАК Регистратор, ДатаВремя(1,1,1) КАК ПериодСекунда, ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Организация КАК Организация, ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Контрагент,
// #14300 в СуммаПриход, СуммаРасход отражаем одну и ту же сумму, ПриКомпоновке ячейки объединяются ВЫБОР КОГДА &НачалоПериодаДляОстатков = ДатаВремя(1,1,1) ТОГДА 0 //КОГДА ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) > 0 // ТОГДА ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) //ИНАЧЕ 0 ИНАЧЕ ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) КОНЕЦ КАК СуммаПриход, ВЫБОР КОГДА &НачалоПериодаДляОстатков = ДатаВремя(1,1,1) ТОГДА 0 //КОГДА ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) < 0 // ТОГДА -ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) //ИНАЧЕ 0 ИНАЧЕ ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) КОНЕЦ КАК СуммаРасход,
ВЫБОР КОГДА &НачалоПериодаДляОстатков = ДатаВремя(1,1,1) ТОГДА 0 ИНАЧЕ ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) КОНЕЦ КАК СуммаОборот, ВЫБОР КОГДА &НачалоПериодаДляОстатков = ДатаВремя(1,1,1) ТОГДА 0 ИНАЧЕ ЕСТЬNULL(БонусыКонтрагентовОстатки.СуммаОстаток, 0) КОНЕЦ КАК СуммаБонусовОборот, ВЫБОР КОГДА &НачалоПериодаДляОстатков = ДатаВремя(1,1,1) ТОГДА 0 ИНАЧЕ ЕСТЬNULL(БонусыКонтрагентовОстатки.СуммаОстаток, 0) КОНЕЦ КАК СуммаБонусовПриход, ВЫБОР КОГДА &НачалоПериодаДляОстатков = ДатаВремя(1,1,1) ТОГДА 0 ИНАЧЕ ЕСТЬNULL(БонусыКонтрагентовОстатки.СуммаОстаток, 0) КОНЕЦ КАК СуммаБонусовРасход ИЗ РегистрНакопления.ВзаиморасчетыСКонтрагентами.ОстаткиИОбороты() КАК ВзаиморасчетыСКонтрагентамиОстаткиИОбороты
ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ВзаиморасчетыСКонтрагентами.Остатки({(&НачалоПериодаДляОстатков)}) КАК ВзаиморасчетыСКонтрагентамиОстатки ПО ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Контрагент = ВзаиморасчетыСКонтрагентамиОстатки.Контрагент
ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.БонусыКонтрагентов.Остатки({(&НачалоПериодаДляОстатков)}) КАК БонусыКонтрагентовОстатки ПО ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Контрагент = БонусыКонтрагентовОстатки.Контрагент

// №13246 // запрос строится именно в таком варианте: // ВзаиморасчетыСКонтрагентамиОстаткиИОбороты - берутся для получения контрагентов, по которым будет выводится строчка "Начальный долг" // если брать только остатки на начало периода, или только обороты, то каких-то контрагентов может не оказаться и строчки "Начальный долг не будет" // с этого запроса не используется получение СуммаНачальныйОстаток, т.к. она виртуальная и рассчитывается на каждый регистратор
ВЫБРАТЬ РАЗРЕШЕННЫЕ 4 КАК Приоритет, "Остатки" КАК Таблица, "ВзаиморасчетыСКонтрагентами" КАК Раздел, "Конечный остаток" КАК Регистратор, ДатаВремя(1,1,1) КАК ПериодСекунда, ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Организация КАК Организация, ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Контрагент,
// #14300 в СуммаПриход, СуммаРасход отражаем одну и ту же сумму, ПриКомпоновке ячейки объединяются ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) КАК СуммаПриход, ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) КАК СуммаРасход,
ЕСТЬNULL(ВзаиморасчетыСКонтрагентамиОстатки.СуммаОстаток, 0) КАК СуммаОборот, ЕСТЬNULL(БонусыКонтрагентовОстатки.СуммаОстаток, 0) КАК СуммаБонусовОборот, ЕСТЬNULL(БонусыКонтрагентовОстатки.СуммаОстаток, 0) КАК СуммаБонусовПриход, ЕСТЬNULL(БонусыКонтрагентовОстатки.СуммаОстаток, 0) КАК СуммаБонусовРасход ИЗ РегистрНакопления.ВзаиморасчетыСКонтрагентами.ОстаткиИОбороты() КАК ВзаиморасчетыСКонтрагентамиОстаткиИОбороты
ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ВзаиморасчетыСКонтрагентами.Остатки({&КонецПериода}) КАК ВзаиморасчетыСКонтрагентамиОстатки ПО ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Контрагент = ВзаиморасчетыСКонтрагентамиОстатки.Контрагент
ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.БонусыКонтрагентов.Остатки(&КонецПериода) КАК БонусыКонтрагентовОстатки ПО ВзаиморасчетыСКонтрагентамиОстаткиИОбороты.Контрагент = БонусыКонтрагентовОстатки.Контрагент

ВЫБРАТЬ РАЗРЕШЕННЫЕ "Взаиморасчеты" КАК Таблица, "БонусыКонтрагентов" КАК Раздел, 2 КАК Приоритет, "" КАК ПустаяСтрока, БонусыКонтрагентовОстаткиИОбороты.Регистратор КАК Регистратор, ВзаиморасчетыСКонтрагентами.Организация КАК Организация, БонусыКонтрагентовОстаткиИОбороты.ПериодСекунда КАК ПериодСекунда, БонусыКонтрагентовОстаткиИОбороты.Контрагент КАК Контрагент, БонусыКонтрагентовОстаткиИОбороты.СуммаОборот КАК СуммаБонусовОборот, БонусыКонтрагентовОстаткиИОбороты.СуммаПриход КАК СуммаБонусовПриход, БонусыКонтрагентовОстаткиИОбороты.СуммаРасход КАК СуммаБонусовРасход, БонусыКонтрагентовОстаткиИОбороты.СуммаНачальныйОстаток КАК СуммаБонусовНачальныйОстаток, БонусыКонтрагентовОстаткиИОбороты.СуммаКонечныйОстаток КАК СуммаБонусовКонечныйОстаток
ИЗ РегистрНакопления.БонусыКонтрагентов.ОстаткиИОбороты(,, Авто) КАК БонусыКонтрагентовОстаткиИОбороты
// Только те, которые есть во взаиморасчетах ВНУТРЕННЕЕ СОЕДИНЕНИЕ (ВЫБРАТЬ РАЗЛИЧНЫЕ ВзаиморасчетыСКонтрагентами.Регистратор КАК Регистратор, ВзаиморасчетыСКонтрагентами.Организация КАК Организация ИЗ РегистрНакопления.ВзаиморасчетыСКонтрагентами КАК ВзаиморасчетыСКонтрагентами) КАК ВзаиморасчетыСКонтрагентами ПО БонусыКонтрагентовОстаткиИОбороты.Регистратор = ВзаиморасчетыСКонтрагентами.Регистратор
